import re
from datetime import datetime

text = data['reads'][0]['result']

def unfold_ics(s):
    lines = s.splitlines()
    out = []
    for line in lines:
        if line.startswith(' ') or line.startswith('\t'):
            if out:
                out[-1] += line[1:]
            else:
                out.append(line[1:])
        else:
            out.append(line)
    return out

def unescape_text(v):
    v = v.replace('\\\\', '\0')
    v = v.replace('\\n', '\n').replace('\\N', '\n')
    v = v.replace('\\,', ',').replace('\\;', ';')
    v = v.replace('\0', '\\')
    return v

def parse_dt(v):
    if re.fullmatch(r'\d{8}', v):
        return datetime.strptime(v, '%Y%m%d').strftime('%Y-%m-%d 00:00:00')
    if re.fullmatch(r'\d{8}T\d{6}Z?', v):
        vv = v[:-1] if v.endswith('Z') else v
        return datetime.strptime(vv, '%Y%m%dT%H%M%S').strftime('%Y-%m-%d %H:%M:%S')
    raise ValueError

try:
    lines = unfold_ics(text)
    events = []
    in_event = False
    current = None

    for line in lines:
        if line == 'BEGIN:VEVENT':
            in_event = True
            current = {}
            continue
        if line == 'END:VEVENT':
            if in_event and current is not None:
                events.append(current)
            in_event = False
            current = None
            continue
